"""Extracted practice data for 천일문 Grammar 1 chapter 01 (from SB/WB page scans).

Student book: uploads/ch01-sb.pdf (printed pp. 12–17).
Workbook: uploads/ch01-wb.pdf (printed pp. 2–7).
Answer keys (accepts only): keys-part3.pdf (WB pp. 34–35).

Regenerate JSON: python3 _extracted_ch01.py
"""
from __future__ import annotations

import base64
import json
import os
import zlib

_SNAPSHOT_B64 = ""


def build_ch01() -> dict[str, dict]:
    """Return all 16 chapter-01 practice documents."""
    raw = zlib.decompress(base64.b64decode(_SNAPSHOT_B64))
    return json.loads(raw)


if __name__ == "__main__":
    root = os.path.join(os.path.dirname(__file__), "..", "..", "data", "chunilmun1", "chapter01")
    docs = build_ch01()
    for name, doc in docs.items():
        path = os.path.join(root, name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(doc, f, ensure_ascii=False, indent=2)
            f.write("\n")
    print(f"chapter 01: wrote {len(docs)} files")
